    "use strict";

    var _ = require('lodash');

    var config = require('../config');

    var path = require('path');

    var fs = require('fs');

    var express = require('express');

    var router = express.Router();

    var request = require('request');

    var cheerio = require('cheerio');

    var cheerioLoad = function (url) {
        return new Promise(function (resolve, reject) {
            request(url, function (error, response, body) {
                if (!error && response.statusCode === 200) {
                    resolve(cheerio.load(body));
                } else {
                    reject(error);
                }
            });
        });
    };

    router.get('/api/robots.txt', function (req, res) {
        res.type('text/plain');
        res.send('User-agent: *');
        res.send('Disallow: /');
    });

    router.get('/api/:url', function (req, res) {
        var url = req.params.url;

        if (_.includes(config.blacklist, url)) {
            res.status(403);
            res.json({ error: 'Not allowed' });
            return;
        }

        cheerioLoad(url)
            .then(function ($) {
                var $body = $('body');
                var $title = $('title');
                var $metaDescription = $('meta[name="description"]');
                var $metaKeywords = $('meta[name="keywords"]');
                var $ogTitle = $('meta[property="og:title"]');
                var $ogDescription = $('meta[property="og:description"]');
                var $ogImage = $('meta[property="og:image"]');

                var title = $title.text();
                var description = $metaDescription.attr('content') || $body.text().trim();
                var keywords = $metaKeywords.attr('content') || '';
                var ogTitle = $ogTitle.attr('content') || title;
                var ogDescription = $ogDescription.attr('content') || description;
                var ogImage = $ogImage.attr('content') || '';

                res.json({
                    title: title,
                    description: description,
                    keywords: keywords,
                    ogTitle: ogTitle,
                    ogDescription: ogDescription,
                    ogImage: ogImage
                });
            })
            .catch(function (error) {
                res.status(500);
                res.json({ error: 'Error fetching data from ' + url });
            });
    });

    module.exports = router;

