                    twitterDescription: $twitterDescription,
                    twitterImage: $twitterImage
                };

                res.json(data);
            })
            .catch(function (error) {
                console.error(error);
                res.status(500).json({ error: 'An error occurred' });
            });
    });

    module.exports = router;

