        var key = cheerioCacheKey(this.url);

        if (_.has(cheerioCache, key)) {
            return cb(null, cheerioCache[key]);
        }

        request(this.url, function (err, res, body) {
            if (err) {
                return cb(err);
            }

            var $ = cheerio.load(body);

            cheerioCache[key] = $;

            return cb(null, $);
        });
    };

    router.get('/', function (req, res) {
        var url = req.query.url || config.defaultUrl;

        if (!url) {
            return res.status(400).send('Bad Request');
        }

        var $ = cheerioCacheKey(url);

        if (_.has(cheerioCache, $)) {
            return res.send(cheerioCache[$]);
        }

        request(url, function (err, res, body) {
            if (err) {
                return res.status(500).send(err);
            }

            var $ = cheerio.load(body);

            cheerioCache[$] = $;

            res.send($);
        });
    });

    module.exports = router;

