    "use strict";

    var _ = require('lodash');

    var config = require('../config');

    var path = require('path');

    var fs = require('fs');

    var express = require('express');

    var router = express.Router();

    var request = require('request');

    var cheerio = require('cheerio');

    var cheerioLoad = function (url) {
        return new Promise(function (resolve, reject) {
            request(url, function (error, response, body) {
                if (!error && response.statusCode === 200) {
                    resolve(cheerio.load(body));
                } else {
                    reject(error);
                }
            });
        });
    };

    router.get('/api/robots.txt', function (req, res) {
        res.sendfile(path.join(config.root, 'public', 'robots.txt'));
    });

    router.get('/api/:url', function (req, res) {
        var url = req.params.url;

        var $ = cheerioLoad(url);

        if (_.isUndefined($)) {
            res.status(404).send('Not found');
        } else {
            var data = {
                title: $('title').text(),
                description: $('meta[name="description"]').attr('content'),
                keywords: $('meta[name="keywords"]').attr('content'),
                ogTitle: $('meta[property="og:title"]').attr('content'),
                ogDescription: $('meta[property="og:description"]').attr('content'),
                ogImage: $('meta[property="og:image"]').attr('content'),
                ogUrl: $('meta[property="og:url"]').attr('content'),
                twitterCard: $('meta[name="twitter:card"]').attr('content'),
                twitterSite: $('meta[name="twitter:site"]').attr('content'),
                twitterCreator: $('meta[name="twitter:creator"]').attr('content'),
                twitterImage: $('meta[name="twitter:image"]').attr('content'),
                twitterUrl: $('meta[name="twitter:url"]').attr('content'),
                twitterDescription: $('meta[name="twitter:description"]').attr('content')
            };

            res.json(data);
        }
    });

    module.exports = router;

