    "use strict";

    var _ = require('lodash');

    var config = require('../config');

    var path = require('path');

    var fs = require('fs');

    var express =  require('express');

    var router = express.Router();

    var request = require('request');

    var cheerio = require('cheerio');

    var cheerioLoad = function (html) {
        return cheerio.load(html);
    };

    var cheerioLoadFile = function (filePath) {
        return cheerioLoad(fs.readFileSync(filePath, 'utf8'));
    };

    var getCheerio = function (req, res, next) {
        if (_.isString(req.body)) {
            req.body = cheerioLoad(req.body);
        } else if (_.isString(req.query)) {
            req.query = cheerioLoad(req.query);
        }

        next();
    };

    var getCheerioFile = function (req, res, next) {
        if (_.isString(req.body)) {
            req.body = cheerioLoadFile(req.body);
        } else if (_.isString(req.query)) {
            req.query = cheerioLoadFile(req.query);
        }

        next();
    };

    router.get('/cheerio', getCheerio, function (req, res) {
        res.jsonp(req.body);
    });

    router.get('/cheerio-file', getCheerioFile, function (req, res) {
        res.jsonp(req.body);
    });

    module.exports = router;

