    "use strict";

    var _ = require('lodash');

    var config = require('../config');

    var path = require('path');

    var fs = require('fs');

    var express = require('express');

    var router = express.Router();

    var request = require('request');

    var cheerio = require('cheerio');

    var cheerioLoad = require('cheerio-load');

    var cheerioCache = {};

    var cheerioCacheKey = function (url) {
        return 'cheerio:' + url;
    };

    var cache = function (cb) {
        var key = cheerioCacheKey(this.url);

        if (_.has(cheerioCache, key)) {
            return cb(null, cheerioCache[key]);
        }

        var deferred = Q.defer();

        request(this.url, function (error, response, body) {
            if (!error && response.statusCode === 200) {
                var $ = cheerio.load(body);
                cheerioCache[key] = $;

                deferred.resolve($);
            } else {
                deferred.reject(error);
            }
        });

        return deferred.promise.nodeify(cb);
    };

    router.get('/', function (req, res) {
        var url = req.query.url;

        if (_.isString(url)) {
            var $ = cheerioCacheKey(url);

            if (_.has(cheerioCache, $)) {
                res.send(cheerioCache[$]);
            } else {
                request(url, function (error, response, body) {
                    if (!error && response.statusCode === 200) {
                        var $ = cheerio.load(body);
                        cheerioCache[$] = $;

                        res.send($);
                    } else {
                        res.status(500).send(error);
                    }
                });
            }
        } else {
            res.status(400).send('Bad Request');
        }
    });

    module.exports = router;

